# ── Database ──────────────────────────────────────────────────
db = sqlite3.connect("aria.db", check_same_thread=False)
db.row_factory = sqlite3.Row
db.executescript("""
CREATE TABLE IF NOT EXISTS events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL, description TEXT,
    start_time TEXT NOT NULL, end_time TEXT,
    location TEXT, source TEXT DEFAULT 'local',
    created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL, description TEXT,
    status TEXT DEFAULT 'pending',
    priority TEXT DEFAULT 'medium',
    due_date TEXT, category TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    completed_at TEXT
);
CREATE TABLE IF NOT EXISTS reminders (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL, description TEXT,
    trigger_time TEXT NOT NULL,
    type TEXT DEFAULT 'reminder',
    is_active INTEGER DEFAULT 1,
    is_triggered INTEGER DEFAULT 0,
    created_at TEXT DEFAULT (datetime('now'))
);
""")
db.commit()

# ── Scheduler ─────────────────────────────────────────────────
scheduler = BackgroundScheduler()
scheduler.start()
active_ws: list = []

def fire_reminder(rid: int, title: str):
    db.execute("UPDATE reminders SET is_triggered=1 WHERE id=?", (rid,))
    db.commit()
    asyncio.run(_broadcast({"type": "reminder", "id": rid, "title": title}))

async def _broadcast(msg: dict):
    for ws in list(active_ws):
        try: await ws.send_json(msg)
        except: pass

def schedule_reminder(rid: int, trigger_iso: str, title: str):
    t = datetime.fromisoformat(trigger_iso)
    if t <= datetime.utcnow(): return
    scheduler.add_job(fire_reminder, "date", run_date=t,
                      id=f"r{rid}", args=[rid, title], replace_existing=True)

# Reload active reminders on startup
for row in db.execute("SELECT id,title,trigger_time FROM reminders WHERE is_active=1 AND is_triggered=0").fetchall():
    schedule_reminder(row["id"], row["trigger_time"], row["title"])

# ── AI Brain ──────────────────────────────────────────────────
SYSTEM = """You are ARIA — a friendly personal assistant.
You manage calendars, tasks, reminders, and emails.
Resolve relative dates (tomorrow, next Monday, in 2 hours) using the current datetime provided.
Be concise and friendly. Confirm actions clearly after completing them."""

TOOLS = [
    {"name":"get_current_datetime","description":"Get current date and time","input_schema":{"type":"object","properties":{}}},
    {"name":"get_upcoming_events","description":"Get upcoming calendar events","input_schema":{"type":"object","properties":{"days":{"type":"integer","default":7}}}},
    {"name":"create_event","description":"Create a calendar event","input_schema":{"type":"object","properties":{"title":{"type":"string"},"start_time":{"type":"string","description":"ISO datetime"},"end_time":{"type":"string"},"description":{"type":"string"},"location":{"type":"string"}},"required":["title","start_time"]}},
    {"name":"delete_event","description":"Delete event by id","input_schema":{"type":"object","properties":{"event_id":{"type":"integer"}},"required":["event_id"]}},
    {"name":"create_task","description":"Create a task","input_schema":{"type":"object","properties":{"title":{"type":"string"},"description":{"type":"string"},"priority":{"type":"string","enum":["low","medium","high","urgent"],"default":"medium"},"due_date":{"type":"string"},"category":{"type":"string"}},"required":["title"]}},
    {"name":"get_tasks","description":"Get tasks","input_schema":{"type":"object","properties":{"status":{"type":"string","enum":["pending","in_progress","completed","all"]},"category":{"type":"string"}}}},
    {"name":"complete_task","description":"Mark task completed","input_schema":{"type":"object","properties":{"task_id":{"type":"integer"}},"required":["task_id"]}},
    {"name":"delete_task","description":"Delete task","input_schema":{"type":"object","properties":{"task_id":{"type":"integer"}},"required":["task_id"]}},
    {"name":"set_reminder","description":"Set a reminder","input_schema":{"type":"object","properties":{"title":{"type":"string"},"trigger_time":{"type":"string","description":"ISO datetime"},"description":{"type":"string"}},"required":["title","trigger_time"]}},
    {"name":"set_alarm","description":"Set an alarm","input_schema":{"type":"object","properties":{"title":{"type":"string"},"trigger_time":{"type":"string"}},"required":["title","trigger_time"]}},
    {"name":"get_reminders","description":"Get all reminders","input_schema":{"type":"object","properties":{}}},
    {"name":"cancel_reminder","description":"Cancel a reminder","input_schema":{"type":"object","properties":{"reminder_id":{"type":"integer"}},"required":["reminder_id"]}},
]

client = anthropic.Anthropic(api_key=API_KEY)
history: list = []

def run_tool(name: str, inp: dict) -> str:
    try:
        if name == "get_current_datetime":
            return json.dumps({"datetime": datetime.now().isoformat()})

        elif name == "get_upcoming_events":
            days = inp.get("days", 7)
            end = (datetime.utcnow() + timedelta(days=days)).isoformat()
            rows = db.execute("SELECT * FROM events WHERE start_time >= datetime('now') AND start_time <= ? ORDER BY start_time", (end,)).fetchall()
            return json.dumps([dict(r) for r in rows])

        elif name == "create_event":
            db.execute("INSERT INTO events (title,description,start_time,end_time,location) VALUES (?,?,?,?,?)",
                (inp["title"], inp.get("description",""), inp["start_time"],
                 inp.get("end_time"), inp.get("location","")))
            db.commit()
            return json.dumps({"success": True, "title": inp["title"]})

        elif name == "delete_event":
            db.execute("DELETE FROM events WHERE id=?", (inp["event_id"],))
            db.commit()
            return json.dumps({"success": True})

        elif name == "create_task":
            db.execute("INSERT INTO tasks (title,description,priority,due_date,category) VALUES (?,?,?,?,?)",
                (inp["title"], inp.get("description",""), inp.get("priority","medium"),
                 inp.get("due_date"), inp.get("category")))
            db.commit()
            return json.dumps({"success": True, "title": inp["title"]})

        elif name == "get_tasks":
            status = inp.get("status")
            q = "SELECT * FROM tasks"
            params = []
            if status and status != "all":
                q += " WHERE status=?"
                params.append(status)
            elif not status:
                q += " WHERE status IN ('pending','in_progress')"
            q += " ORDER BY due_date ASC"
            rows = db.execute(q, params).fetchall()
            return json.dumps([dict(r) for r in rows])

        elif name == "complete_task":
            db.execute("UPDATE tasks SET status='completed',completed_at=datetime('now') WHERE id=?", (inp["task_id"],))
            db.commit()
            return json.dumps({"success": True})

        elif name == "delete_task":
            db.execute("DELETE FROM tasks WHERE id=?", (inp["task_id"],))
            db.commit()
            return json.dumps({"success": True})

        elif name in ("set_reminder","set_alarm"):
            t = inp.get("trigger_time")
            rtype = "alarm" if name == "set_alarm" else "reminder"
            cur = db.execute("INSERT INTO reminders (title,description,trigger_time,type) VALUES (?,?,?,?)",
                (inp["title"], inp.get("description",""), t, rtype))
            db.commit()
            rid = cur.lastrowid
            schedule_reminder(rid, t, inp["title"])
            return json.dumps({"success": True, "id": rid})

        elif name == "get_reminders":
            rows = db.execute("SELECT * FROM reminders WHERE is_active=1 AND is_triggered=0 ORDER BY trigger_time").fetchall()
            return json.dumps([dict(r) for r in rows])

        elif name == "cancel_reminder":
            db.execute("UPDATE reminders SET is_active=0 WHERE id=?", (inp["reminder_id"],))
            db.commit()
            scheduler.remove_job(f"r{inp['reminder_id']}", jobstore=None)
            return json.dumps({"success": True})

        return json.dumps({"error": f"unknown tool {name}"})
    except Exception as e:
        return json.dumps({"error": str(e)})

def chat(message: str) -> str:
    now = datetime.now().strftime("%A, %B %d, %Y %H:%M")
    history.append({"role":"user","content":f"[Now: {now}]\n\n{message}"})
    while True:
        resp = client.messages.create(
            model="claude-sonnet-4-6", max_tokens=4096,
            system=SYSTEM, tools=TOOLS, messages=history)
        if resp.stop_reason == "end_turn":
            text = next((b.text for b in resp.content if hasattr(b,"text")), "")
            history.append({"role":"assistant","content":resp.content})
            return text
        elif resp.stop_reason == "tool_use":
            history.append({"role":"assistant","content":resp.content})
            results = []
            for b in resp.content:
                if b.type == "tool_use":
                    results.append({"type":"tool_result","tool_use_id":b.id,"content":run_tool(b.name,b.input)})
            history.append({"role":"user","content":results})
        else:
            break
    return "Sorry, something went wrong. Please try again."

